Here's an iterative flood-fill solution (uses an explicit stack, so it won't hit recursion limits on large grids):

```python
from collections import deque


def count_islands(grid) -> int:
    if not grid:
        return 0

    rows = len(grid)
    cols = len(grid[0]) if grid[0] is not None else 0
    if cols == 0:
        return 0

    seen = [[False] * len(grid[r]) for r in range(rows)]
    count = 0

    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] != '#' or seen[r][c]:
                continue
            count += 1
            stack = deque([(r, c)])
            seen[r][c] = True
            while stack:
                i, j = stack.pop()
                for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ni, nj = i + di, j + dj
                    if 0 <= ni < rows and 0 <= nj < len(grid[ni]):
                        if grid[ni][nj] == '#' and not seen[ni][nj]:
                            seen[ni][nj] = True
                            stack.append((ni, nj))
    return count
```

Each unvisited land cell starts a new island and its whole connected component is marked visited, so every island is counted exactly once. An empty grid (or one with empty rows) returns 0.
